package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.stream.Stream;
import java.util.zip.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;
import static org.junit.jupiter.api.Assertions.*;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

class DndscvWorkflowTest {
    @TempDir static Path corpus;@TempDir Path temporary;static Map<String,byte[]> originals;
    static Object parse(byte[] raw)throws IOException{return NextflowParameters.parse(NextflowFiles.utf8(raw),32<<20,5000000);}
    static Map<String,Object> json(Path path)throws IOException{return object(parse(Files.readAllBytes(path)));}
    static void save(Path path,Object value)throws IOException{Files.writeString(path,NextflowJson.json(value)+"\n",StandardCharsets.UTF_8);}
    @BeforeAll static void load()throws Exception{
        var files=new LinkedHashMap<String,byte[]>();try(var zip=new ZipInputStream(Objects.requireNonNull(DndscvWorkflowTest.class.getResourceAsStream("/org/jlinalg/genetics/dndscv/workflow-transports-v2.zip")))){for(var entry=zip.getNextEntry();entry!=null;entry=zip.getNextEntry()){NextflowFiles.member(entry.getName());byte[] bytes=zip.readNBytes(32<<20);assertTrue(bytes.length<(32<<20));assertNull(files.put(entry.getName(),bytes));}}
        var index=object(object(parse(files.get("INDEX.json"))).get("files"));assertEquals(index.size()+1,files.size());for(var e:index.entrySet()){byte[] bytes=Objects.requireNonNull(files.get(e.getKey()));var pin=object(e.getValue());assertEquals(integer(pin.get("bytes"),0,32<<20),bytes.length);assertEquals(text(pin.get("sha256")),NextflowFiles.sha(bytes));Path target=corpus.resolve(e.getKey()).normalize();assertTrue(target.startsWith(corpus));Files.createDirectories(target.getParent());Files.write(target,bytes);}originals=Map.copyOf(files);
    }
    @AfterAll static void unchanged()throws IOException{for(var e:originals.entrySet())if(!e.getKey().equals("INDEX.json"))assertArrayEquals(e.getValue(),Files.readAllBytes(corpus.resolve(e.getKey())));}
    static Map<String,Object> rawRequest()throws IOException{var raw=json(corpus.resolve("source-request.json"));raw.put("mutations","inputs/mutations.tsv");var genes=object(raw.get("genes"));genes.put("file","inputs/genes.tsv");raw.put("genes",genes);return raw;}
    static DndscvWorkflowRequest.Request request(Path root,Map<String,Object> changes)throws IOException{var raw=rawRequest();raw.putAll(changes);return DndscvWorkflowRequest.parse(raw,root);}
    static Stream<String> cases(){return Stream.of("targeted-192","targeted-2","one-sided-selection");}
    static void copy(Path from,Path to)throws IOException{try(var paths=Files.walk(from)){for(Path path:paths.toList()){Path target=to.resolve(from.relativize(path));if(Files.isDirectory(path))Files.createDirectories(target);else Files.copy(path,target);}}}
    Map<String,Object> audit(Path home,String id)throws IOException{var r=request(corpus,Map.of());var meter=new DndscvWorkflowInputs.Budget(r.auditOperations());var population=DndscvWorkflowInputs.validate(corpus.resolve("inputs"),r,meter);var refs=DndscvWorkflowAudit.constructed(corpus.resolve("worker"),population,r,meter);var option=r.analyses().stream().filter(a->a.get("id").equals(id)).findFirst().orElseThrow();return DndscvWorkflowAudit.analysis(home,option,refs,population,r,meter);}
    Path caseCopy()throws IOException{Path home=temporary.resolve("case");copy(corpus.resolve("worker/cases/targeted-192"),home);return home;}
    @ParameterizedTest @MethodSource("cases") void completeOriginalModelsArraysAndEventAccounting(String id)throws IOException{Path home=temporary.resolve(id);copy(corpus.resolve("worker/cases").resolve(id),home);var report=audit(home,id);assertEquals(75,report.get("reference_genes"));assertEquals(3180,report.get("annotated_gene_events"));assertEquals(2930L,report.get("counted_substitutions"));assertEquals(2,report.get("stop_loss_events_retained_not_counted"));assertEquals(false,report.get("original_optimizers_or_selection_likelihoods_independently_refitted"));assertTrue(Files.readAllLines(home.resolve("native-event-ledger.tsv")).size()>3408);}
    static void arrayChange(Path path,double value)throws IOException{byte[] bytes;try(var in=new GZIPInputStream(Files.newInputStream(path))){bytes=in.readAllBytes();}long bits=Double.doubleToLongBits(value);for(int i=0;i<8;i++)bytes[i]=(byte)(bits>>>(56-8*i));try(var out=new GZIPOutputStream(Files.newOutputStream(path))){out.write(bytes);}}
    static void changeCell(Path descriptor,String column,int row,String value)throws IOException{
        var manifest=json(descriptor);int offset=0;boolean changed=false;for(String part:strings(manifest.get("parts"),10000)){Path path=descriptor.getParent().resolve(part);var fragment=json(path);int n=(int)integer(fragment.get("rows"),0,100000);if(row>=offset+n){offset+=n;continue;}var columns=list(fragment.get("columns"));int index=-1;for(int c=0;c<columns.size();c++){var record=object(columns.get(c));if(!text(record.get("name")).equals(column))continue;var tokens=new ArrayList<Object>(list(record.get("tokens")));tokens.set(row-offset,value);record.put("tokens",tokens);@SuppressWarnings("unchecked") var mutable=(List<Object>)columns;mutable.set(c,record);index=c;break;}assertTrue(index>=0);save(path,fragment);Path tsv=descriptor.resolveSibling(descriptor.getFileName().toString().replaceFirst("[.]json$",".tsv"));var lines=new ArrayList<>(Files.readAllLines(tsv,StandardCharsets.UTF_8));String[] fields=lines.get(row+1).split("\t",-1);fields[index+1]=value;lines.set(row+1,String.join("\t",fields));Files.write(tsv,lines,StandardCharsets.UTF_8);changed=true;break;}assertTrue(changed);
    }
    @Test void rejectsCoherentChangedObservedCounts()throws Exception{Path home=caseCopy();changeCell(home.resolve("genemuts.json"),"n_syn",0,"999");IOException e=assertThrows(IOException.class,()->audit(home,"targeted-192"));assertTrue(e.getMessage().contains("gene count differs"),e.getMessage());}
    @Test void rejectsCompleteNArrayCorruption()throws Exception{Path home=caseCopy();arrayChange(home.resolve("N.f64be.gz"),999);IOException e=assertThrows(IOException.class,()->audit(home,"targeted-192"));assertTrue(e.getMessage().contains("N matrix differs"),e.getMessage());}
    @Test void rejectsOpportunityArrayCorruption()throws Exception{Path home=caseCopy();arrayChange(home.resolve("L.f64be.gz"),999);IOException e=assertThrows(IOException.class,()->audit(home,"targeted-192"));assertTrue(e.getMessage().contains("Original L differs"),e.getMessage());}
    @Test void rejectsCoherentCodingConsequenceChange()throws Exception{Path home=caseCopy();var r=request(corpus,Map.of());var table=DndscvWorkflowTransport.table(home.resolve("annotmuts.json"),r,new DndscvWorkflowInputs.Budget(r.auditOperations()));int row=0;while(table.cell(row,"impact").equals("no-SNV"))row++;changeCell(home.resolve("annotmuts.json"),"aachange",row,"X999X");IOException e=assertThrows(IOException.class,()->audit(home,"targeted-192"));assertTrue(e.getMessage().contains("complete coding annotation differs"),e.getMessage());}
    @Test void rejectsCoherentPoissonResponseChange()throws Exception{Path home=caseCopy();changeCell(home.resolve("poisson-model-rows.json"),"response",0,"999");IOException e=assertThrows(IOException.class,()->audit(home,"targeted-192"));assertTrue(e.getMessage().contains("Poisson response differs"),e.getMessage());}
    @Test void rejectsCoherentBHChange()throws Exception{Path home=caseCopy();changeCell(home.resolve("sel_cv.json"),"qmis_cv",0,"0.999");IOException e=assertThrows(IOException.class,()->audit(home,"targeted-192"));assertTrue(e.getMessage().contains("BH identity differs"),e.getMessage());}
    @Test void rejectsChangedSeed()throws Exception{Path home=caseCopy();var state=json(home.resolve("source-status.json"));state.put("seed",19);save(home.resolve("source-status.json"),state);IOException e=assertThrows(IOException.class,()->audit(home,"targeted-192"));assertTrue(e.getMessage().contains("seed"),e.getMessage());}
    @Test void rejectsCrossFormatTableMismatch()throws Exception{Path home=caseCopy();Path path=home.resolve("genemuts.tsv");Files.writeString(path,Files.readString(path)+"extra\n");IOException e=assertThrows(IOException.class,()->audit(home,"targeted-192"));assertTrue(e.getMessage().contains("TSV"),e.getMessage());}
    void arrayColumn(Path descriptor,List<Integer> dimensions)throws IOException{var manifest=json(descriptor);for(String part:strings(manifest.get("parts"),10000)){Path path=descriptor.getParent().resolve(part);var fragment=json(path);var columns=new ArrayList<Object>(list(fragment.get("columns")));for(int c=0;c<columns.size();c++){var column=object(columns.get(c));if(!text(column.get("name")).equals("impact"))continue;column.put("class",List.of("array"));column.put("original_dim",dimensions);column.put("original_dimnames",null);columns.set(c,column);}fragment.put("columns",columns);save(path,fragment);}}
    @Test void preservesOneDimensionalOriginalColumnShape()throws Exception{Path home=caseCopy();arrayColumn(home.resolve("annotmuts.json"),List.of(3180));assertEquals(2930L,audit(home,"targeted-192").get("counted_substitutions"));}
    @Test void refusesOriginalColumnDimensionMismatch()throws Exception{Path home=caseCopy();arrayColumn(home.resolve("annotmuts.json"),List.of(3180,1));IOException e=assertThrows(IOException.class,()->audit(home,"targeted-192"));assertTrue(e.getMessage().contains("one element per complete table row"),e.getMessage());}
    @Test void refusesUndeclaredAliasesAndHistoricalVersionSubstitution()throws Exception{var raw=rawRequest();raw.put("profile","0.1.0");assertThrows(IOException.class,()->DndscvWorkflowRequest.parse(raw,temporary));var invalid=rawRequest();var genes=object(invalid.get("genes"));genes.put("cdkn2a_policy","rename");invalid.put("genes",genes);assertThrows(IOException.class,()->DndscvWorkflowRequest.parse(invalid,temporary));}
    @Test void oneSidedAndDuplexChoicesCannotSilentlyOverwriteArguments()throws Exception{var raw=rawRequest();var analyses=new ArrayList<Object>(list(raw.get("analyses")));var a=object(analyses.get(0));a.put("one_sided",true);a.put("constrain_truncation",false);analyses.set(0,a);raw.put("analyses",analyses);assertThrows(IOException.class,()->DndscvWorkflowRequest.parse(raw,temporary));var duplex=rawRequest();duplex.put("duplex",Map.of("kind","per-gene","file","depth.tsv"));var changed=new ArrayList<Object>(list(duplex.get("analyses")));a=object(changed.get(0));a.put("max_coding_muts_per_sample",3000);changed.set(0,a);duplex.put("analyses",changed);assertThrows(IOException.class,()->DndscvWorkflowRequest.parse(duplex,temporary));}
    @Test void optionalFilesAndIndependentEventAssertionAreRequiredExactly()throws Exception{var raw=rawRequest();raw.put("gene_sets","unused.tsv");assertThrows(IOException.class,()->DndscvWorkflowRequest.parse(raw,temporary));var missing=rawRequest();missing.remove("independent_events");assertThrows(IOException.class,()->DndscvWorkflowRequest.parse(missing,temporary));}
    @Test void nearIntegerPositionsAreNotRoundedAndLiteralIdsSurvive()throws Exception{Path inputs=temporary.resolve("inputs");Files.createDirectory(inputs);Files.writeString(inputs.resolve("mutations.tsv"),"sample_id\tchromosome\tposition\treference\talternate\nNA\t1\t1.0000000000000001\tA\tT\n");Files.copy(corpus.resolve("inputs/genes.tsv"),inputs.resolve("genes.tsv"));var r=request(temporary,Map.of());assertThrows(IOException.class,()->DndscvWorkflowInputs.validate(inputs,r,new DndscvWorkflowInputs.Budget(r.auditOperations())));Files.writeString(inputs.resolve("mutations.tsv"),"sample_id\tchromosome\tposition\treference\talternate\nNA\t1\t1\tA\tT\nδ\t1\t2\tC\tG\n");var p=DndscvWorkflowInputs.validate(inputs,r,new DndscvWorkflowInputs.Budget(r.auditOperations()));assertEquals(List.of("NA","δ"),p.events().stream().map(e->e.key().sample()).toList());}
}
